      if(this.menu==='victory'){this.host.innerHTML=this.victory();this.restoreFocus(remembered);return;}
      const titles={pause:'A moment of quiet',inventory:'The quartermaster',shop:'Resistance supply',dialogue:'A friendly face',bounty:'The commander bounty center',forge:'The resistance forge',map:'The animal kingdoms',journal:'Orders from the field',skills:'Skills & field abilities',reward:'Choose your reward',settings:'Field preferences',controls:'Know your equipment'};
      const renderers={pause:()=>this.pauseMenu(),inventory:()=>this.inventoryMenu(false),shop:()=>this.inventoryMenu(true),dialogue:()=>this.dialogueMenu(),bounty:()=>this.bountyMenu(),forge:()=>this.forgeMenu(),map:()=>this.mapMenu(),journal:()=>this.journalMenu(),skills:()=>this.skillsMenu(),reward:()=>this.rewardMenu(),settings:()=>this.settingsMenu(),controls:()=>this.controlsMenu()};
      this.host.innerHTML=`<div class="menu-layer"><section class="panel" role="dialog" aria-modal="true" aria-label="${escape(titles[this.menu])}"><header class="panel-header"><div><div class="eyebrow">Resistance field manual</div><h2>${titles[this.menu]||'MeowQuest'}</h2></div><button class="close" data-action="close">Return <kbd>Esc</kbd></button></header>${this.game.state==='playing'?this.nav():''}<div class="panel-content">${(renderers[this.menu]||renderers.pause)()}</div><footer class="panel-footer"><span><kbd>A</kbd> Select <kbd>B</kbd> Back <kbd>LB / RB</kbd> ${this.controllerTabLabel()} <kbd>Start</kbd> ${this.game.state==='playing'?'Resume':'Back'}</span><span>MEOWQUEST · RESISTANCE COMMAND</span></footer></section></div>`;
