        if(style&&!/(auto|scroll)/.test(style.overflowY+' '+style.overflowX))continue;
        const r=control.getBoundingClientRect(),box=parent.getBoundingClientRect(),pad=7,categoryBar=parent===this.host.querySelector?.('.panel-content')?this.host.querySelector?.('.skill-category-tabs'):null,overlay=categoryBar&&!categoryBar.contains?.(control)?(categoryBar.offsetHeight||0)+8:0;
        if(parent.scrollHeight>parent.clientHeight+1){const top=box.top+(parent.clientTop||0)+pad+overlay,bottom=box.top+(parent.clientTop||0)+parent.clientHeight-pad;if(r.top<top)parent.scrollTop+=r.top-top;else if(r.bottom>bottom)parent.scrollTop+=r.bottom-bottom;}
        if(parent.scrollWidth>parent.clientWidth+1){const left=box.left+(parent.clientLeft||0)+pad,right=box.left+(parent.clientLeft||0)+parent.clientWidth-pad;if(r.left<left)parent.scrollLeft+=r.left-left;else if(r.right>right)parent.scrollLeft+=r.right-right;}
        found=true;
