    pauseMenu(){const g=this.game,p=g.players?.[0],lib=g.world?.liberated?.size||0;return `<div class="pause-grid"><div class="pause-links"><button class="primary" data-action="close">Back to the field <span>→</span></button><button data-action="save">Save campaign <span>0${g.slot+1}</span></button><button data-action="menu" data-value="inventory">Equipment & inventory <span>I</span></button><button data-action="menu" data-value="journal">Mission journal <span>J</span></button><button data-action="coop">${g.players?.length>1?'Let Player 2 rest at camp':'Welcome Player 2'} <span>Co-op</span></button>${this.fullscreenButton()}<button data-action="exit">Save & return to title <span>↗</span></button></div><div class="operation-report"><div class="eyebrow">Campaign report</div><h3>The kingdom remembers.</h3><p>Every outpost reclaimed brings the resistance closer to home. Follow roads to friendly settlements for supplies, healing, and your next lead.</p><div class="report-numbers"><div><b>${p?.level||1}</b><small>HERO LEVEL</small></div><div><b>${lib}</b><small>LOCATIONS FREED</small></div><div><b>${g.kills||0}</b><small>ENEMIES DEFEATED</small></div></div><p>Campaign slot 0${g.slot+1} · Both heroes share this adventure and keep their own equipment and skills.</p><p class="small-note" role="status">${escape(this.saveStatusText(g.slot))}</p>${this.saveStatus(g.slot).state==='temporary'?'<p class="save-warning">Browser storage is unavailable. Export a backup from Settings to keep this adventure before reloading or closing the game.</p>':''}</div></div>`;}
    playerTabs(){return `<div class="player-tabs">${(this.game.players||[]).map((p,i)=>`<button class="${i===this.playerIndex?'selected':''}" data-action="player" data-value="${i}">Player ${i+1} · Level ${p.level}</button>`).join('')}<span class="wallet">${Math.floor(this.player()?.gold||0)} gold &nbsp;·&nbsp; ${Math.floor(this.player()?.materials||0)} scrap &nbsp;·&nbsp; ${this.player()?.cores||0} rare cores</span></div>`;}
    player(){return this.game.players?.[this.playerIndex]||this.game.players?.[0];}
    item(id){return (OW.Content.equipment||[]).find(it=>it.id===id);}
    rarity(item){const value=item.rarity;return typeof value==='number'?value:Math.max(0,['common','uncommon','rare','epic','legendary','mythic'].indexOf(String(value).toLowerCase()));}
    rarityName(item){return ['Common','Uncommon','Rare','Epic','Legendary','Mythic'][this.rarity(item)]||'Common';}
    iconIndex(item){if(Number.isInteger(item.icon))return item.icon;const slot=item.slot;const id=item.weapon??item.melee??item.ability??0;if(slot==='weapon'||slot==='firearm'||slot==='secondary'){const kind=OW.Content.weapons[id]?.kind;return {pistol:0,revolver:1,smg:2,rifle:3,shotgun:4,sniper:5,lmg:6,rocket:7,experimental:7}[kind]??3;}return slot==='melee'?8+id%4:slot==='armor'?14:slot==='helmet'?13:slot==='accessory'?27:slot==='ability'?(id===1?24:id===0||id===11?15:12):item.id==='ammo_crate'?25:24;}
    icon(item,large=false){const index=this.iconIndex(item),s=large?105:52;return `<span class="item-icon ${large?'large-icon':''}" role="img" aria-label="${escape(item.name)}" style="background-position:-${(index%8)*s}px -${Math.floor(index/8)*s}px"></span>`;}
