      const stats=[];if(weapon){stats.push(['Damage',weapon.damage]);if(weapon.fireRate)stats.push(['Fire rate',Number(weapon.fireRate).toFixed(1)+'/s']);if(weapon.magazine)stats.push(['Magazine',weapon.magazine]);if(weapon.range)stats.push(['Range',Math.round(weapon.range)]);}if(it.armor)stats.push(['Defense','+'+Math.round(it.armor*100)+'%']);if(it.health)stats.push(['Health','+'+it.health]);if(it.damage)stats.push(['Damage bonus','+'+Math.round(it.damage*100)+'%']);if(ability){stats.push(['Cooldown',ability.cooldown+'s']);stats.push(['Power',ability.damage]);}
      const inv=p.inventory.find(v=>(typeof v==='string'?v:v.id)===it.id),rank=it.weapon!==undefined?(p.weaponUpgrades?.[it.weapon]||0):typeof inv==='object'?inv.upgrade||0:0;
      return `${this.icon(it,true)}<div class="rarity" style="color:${colors[this.rarity(it)]}">${this.rarityName(it)} · ${escape(it.slot)} · LEVEL ${it.level||1}</div><h3>${escape(it.name)}${rank?' +'+rank:''}</h3><p>${escape(it.description||ability?.description||'Resistance field equipment. Built for the long road home.')}</p>${it.rewardSource?`<p class="reward-source"><strong>Earned in the field</strong>${escape(it.rewardSource)}</p>`:''}${weapon?.mechanicName?`<div class="weapon-mechanic"><strong>${escape(weapon.mechanicName)}</strong><p>${escape(weapon.mechanicDescription||'')}</p></div>`:''}${it.melee!==undefined?'<p class="blade-risk">High damage at close range. Strikes have a windup and recovery: movement slows, and you cannot dodge or fire during the commitment. Heavy strikes and attacks from behind hit harder. Miss a swing and you are exposed.</p>':''}${this.comparison(it)}${this.requirement(it)?`<p class="requirement">${escape(this.requirement(it))}</p>`:''}<div class="stats-list">${stats.map(([name,value])=>`<div><span>${name}</span><b>${escape(value)}</b></div>`).join('')}</div>${shop?`<button class="primary" data-action="buy" data-value="${escape(it.id)}" ${(this.owned(it)&&it.slot!=='consumable')||p.gold<this.price(it)||(p.cores||0)<this.coreCost(it)||!!this.requirement(it)?'disabled':''}>${this.owned(it)&&it.slot!=='consumable'?'Already in inventory':`Purchase · ${this.price(it)} gold${this.coreCost(it)?' + '+this.coreCost(it)+' cores':''}`}</button>`:`<button class="primary" data-action="equip" data-value="${escape(it.id)}" ${this.isEquipped(it)?'disabled':''}>${this.isEquipped(it)?'Equipped':it.slot==='consumable'?'Add to field supplies':'Equip '+(it.slot==='ability'?'primary':'')}</button>${it.slot==='ability'?`<button data-action="equip-secondary" data-value="${escape(it.id)}">Equip secondary ability</button>`:''}${it.weapon!==undefined?`<button data-action="equip-secondary-firearm" data-value="${escape(it.id)}" ${p.secondary===it.weapon?'disabled':''}>${p.secondary===it.weapon?'Secondary firearm equipped':'Equip secondary firearm'}</button>`:''}${it.weapon!==undefined&&p.weapon===it.weapon?`<p class="small-note">Visit the resistance forge to improve this firearm. Current upgrade: +${rank}.</p>`:''}`}`;
