    npcPortrait(npc,name){const roles={trader:0,merchant:0,blacksmith:1,engineer:1,farmer:2,ranger:3,scout:3,medic:4,civilian:5,scholar:5},row=Math.max(0,Math.floor(roles[npc.role]??npc.variant??0))%6,base=OW.config?.assetBaseURL||'',path=base?base.replace(/\/$/,'')+'/characters/friendly-cats.png':'assets/characters/friendly-cats.png';return '<span class="forge-portrait npc-portrait" role="img" aria-label="'+escape(name)+' the friendly cat" style="background-image:url(&quot;'+escape(path)+'&quot;);background-position:0 '+(row*20)+'%;background-size:400% 600%"></span>';}
