      return `<div class="campaign-objective"><div><span class="section-label">Operation Whiskerfall</span><strong>${won?'Adolph Whisker defeated · campaign won':fallen===8?'Berlin is open · defeat Adolph Whisker':`${fallen} / 8 regional bosses defeated · Berlin sealed`}</strong><p>${won?'The resistance has won. Your remaining side quests are still available.':fallen===8?'Prepare at a forge, stock up on medicine, and enter the Berlin Sector.':'Defeat every regional commander to break the Berlin lockdown. Bounty posters show each commander’s location.'}</p></div><button data-action="menu" data-value="bounty">View boss posters</button></div>`;
