      p.dialogueMemory=p.dialogueMemory||{};const memory=p.dialogueMemory[npc.id]||(p.dialogueMemory[npc.id]={});memory.met=true;memory.choices=Array.from(new Set([...(memory.choices||[]),choice.id])).slice(-24);if(choice.tone)memory.tone=choice.tone;
      if(choice.mark){const cave=this.game.world.getLocation(choice.mark);if(cave){this.game.world.discovered.add(cave.id);this.game.setMarker(cave.x,cave.y);this.toast(cave.name+' marked on your map.');}}
