    conversationHTML(){const conversation=this.conversation();if(!conversation)return '';return `<div class="conversation-thread" aria-live="polite"><div class="relationship-note">${escape(conversation.relationship)}</div>${this.dialogueLastReply?`<p class="player-reply"><span>You</span>${escape(this.dialogueLastReply)}</p>`:''}${conversation.recall?`<p class="npc-recollection">${escape(conversation.recall)}</p>`:''}${conversation.lines.map(line=>`<p>${escape(line)}</p>`).join('')}<div class="dialogue-replies" aria-label="Your reply">${conversation.choices.map(choice=>`<button data-action="dialogue-reply" data-value="${escape(choice.id)}"><span aria-hidden="true">›</span>${escape(choice.label)}</button>`).join('')}</div></div>`;}
