        const spec=OW.Content.bosses[l.bossIndex??l.region]||{},done=g.bossDefeated?.(l)||g.world.liberated.has(l.id),final=!!(l.final||l.finalBoss||l.bossIndex===8),locked=final&&!(g.berlinUnlocked?.()??g.world.berlinUnlocked?.()),region=g.world.regions[l.region];
