    upgradeButton(p){const rank=p.weaponUpgrades?.[p.weapon]||0,cost=80+75*rank,mats=5+3*rank,cores=rank===5||rank===9?1:0;return '<button data-action="upgrade" '+(rank>=10?'disabled':'')+'>'+(rank>=10?'Firearm fully upgraded':'Upgrade equipped firearm · '+cost+' gold + '+mats+' scrap'+(cores?' + '+cores+' core':''))+'</button><p class="small-note">Firearm upgrades are available at the resistance forge. Current upgrade: +'+rank+'.</p>';}
