        if(this.menu==='dialogue'&&this.dialogueNode&&this.dialogueNode!=='start'){this.dialogueNode='start';this.dialogueLastReply='';this.controllerFocus=[null,null];this.render();return;}
        if(this.menu==='dialogue'&&this.dialogueTopic&&this.dialogueTopic!=='story'){this.dialogueTopic='story';this.controllerFocus=[null,null];this.render();return;}
