        if(current.type==='range'){const step=Number(current.step)||.05,min=current.min===''?0:Number(current.min),max=current.max===''?100:Number(current.max);current.value=String(Number(Math.min(max,Math.max(min,Number(current.value)+direction*step)).toFixed(5)));current.dispatchEvent(new Event('input',{bubbles:true}));return;}
